                <div class="col-span-3 text-center py-20 text-gray-400 bg-mocco-card rounded-2xl">
                    <i class="fa-brands fa-youtube text-4xl mb-4 opacity-50"></i>
                    <p>Proximamente podras consultar nuestros contenidos extendidos.</p>
                </div>
            <?php endif; ?>
        </div>
    </section>

</main>

<!-- JS para el carrusel de notas -->
<?php if(!empty($hero_slides)): ?>
<script>
    const heroData = <?php echo json_encode($hero_slides); ?>;
    function changeHero(index) {
        if (!heroData[index]) return;
        document.getElementById('hero-title').innerText = heroData[index].title;
        document.getElementById('hero-category').innerText = heroData[index].cat;
        document.getElementById('hero-link').href = heroData[index].link;
        document.getElementById('hero-container').style.backgroundImage = `url('${heroData[index].img}')`;
        
        document.querySelectorAll('.hero-dot').forEach((dot, i) => {
            if (i === index) {
                dot.className = 'hero-dot w-8 h-1 rounded-full transition-all duration-300 bg-white';
            } else {
                dot.className = 'hero-dot w-8 h-1 rounded-full transition-all duration-300 bg-white/30 hover:bg-white/60';
            }
        });
    }
</script>
<?php endif; ?>

